import{_ as t,o,c as r,a2 as s}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Architecture guard scripts (maintainer guide)","description":"","frontmatter":{},"headers":[],"relativePath":"release/guard-scripts.md","filePath":"release/guard-scripts.md"}'),d={name:"release/guard-scripts.md"};function a(c,e,i,n,l,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="architecture-guard-scripts-maintainer-guide" tabindex="-1">Architecture guard scripts (maintainer guide) <a class="header-anchor" href="#architecture-guard-scripts-maintainer-guide" aria-label="Permalink to &quot;Architecture guard scripts (maintainer guide)&quot;">​</a></h1><p>The checker scripts that turn structural invariants into hard failures. Every guard below is documented as <strong>input → check logic → failure output → where it is enforced</strong>. Related pages: <a href="./build-reference.html">build-reference</a> for the rules that host these guards, <a href="./ci-gates.html">ci-gates</a> for the CI-side gates, <a href="./tool-inventory.html">tool-inventory</a> for the full tools/ listing.</p><p>The guard philosophy of this repo: an invariant that once failed live (the incident is cited in each section) becomes a script that fails the build/release, so the same class of bug can never ship silently again.</p><h2 id="_1-tools-check-deps-py-—-dependency-direction-gate" tabindex="-1">1. tools/check_deps.py — dependency-direction gate <a class="header-anchor" href="#_1-tools-check-deps-py-—-dependency-direction-gate" aria-label="Permalink to &quot;1. tools/check_deps.py — dependency-direction gate&quot;">​</a></h2><p><strong>What it guards</strong>: the layering of the <code>ocos/</code> tree.</p><table tabindex="0"><thead><tr><th>Layer</th><th>May NOT depend on</th></tr></thead><tbody><tr><td><code>ocos/kernel/</code></td><td><code>ocos/drivers/</code>, <code>ocos/services/</code> (nothing above the mechanism layer)</td></tr><tr><td><code>ocos/drivers/</code></td><td><code>ocos/services/</code></td></tr><tr><td><code>ocos/l1apps/</code></td><td><code>ocos/kernel/</code>, <code>ocos/drivers/</code>, <code>ocos/services/</code> — only <code>ocos/interface/</code>-owned headers</td></tr></tbody></table><p><strong>Input</strong>: nothing (walks the working tree from the repo root).</p><p><strong>Check logic</strong>:</p><ol><li>Build a basename → owning-layer map by walking <code>ocos/{kernel,drivers,services,interface}</code> for <code>.h</code>/<code>.c</code> files. Includes are plain basenames resolved against this real inventory — exactly how the build&#39;s multi-<code>-I</code> strategy resolves them.</li><li>For every <code>.c</code>/<code>.h</code> under the guarded layers, read each <code>#include &quot;x.h&quot;</code> line (quoted includes only, no path separators) and resolve <code>x.h</code> against the inventory.</li><li>Skip the composition root: <code>kernel/core_boot_*.c</code> may depend on every layer by design (it is the top of the chain); the two registration frameworks include each other&#39;s owning headers by design.</li></ol><p><strong>Failure output</strong> (exit 1):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>check_deps: N DEPENDENCY-DIRECTION VIOLATIONS:</span></span>\n<span class="line"><span>  kernel/foo.c:12: includes &#39;bar.h&#39; -&gt; drivers/baz/bar.h (forbidden direction)</span></span></code></pre></div><p>Success prints the scanned-file count and <code>0 violations (kernel -&gt; nothing above it; drivers -&gt; no services; l1apps -&gt; interface only)</code>.</p><p><strong>Enforced where</strong>: manual / pre-release hygiene runs (<code>python3 tools/check_deps.py</code>). It is not wired into CI and not into <code>make</code> — run it before structural changes and before a release. Note that the l1apps constraint is already half-enforced by the build&#39;s <code>-I</code> set (the compile fails when an app reaches outside <code>ocos/interface/</code>); this gate double-checks it statically.</p><h2 id="_2-tools-check-bss-py-—-boot-zone-bss-gate" tabindex="-1">2. tools/check_bss.py — boot-zone .bss gate <a class="header-anchor" href="#_2-tools-check-bss-py-—-boot-zone-bss-gate" aria-label="Permalink to &quot;2. tools/check_bss.py — boot-zone .bss gate&quot;">​</a></h2><p><strong>What it guards</strong>: no regular <code>.bss</code> variable may land in the boot structure zone. <code>core_boot_entry.S</code> reserves the page tables (PML4/PDPT/PD) and the boot stack INSIDE <code>.bss</code>; the linker happily places other objects below them. The WP-06b b4 session live-caught the consequence: a 64 KiB CLI buffer landed on the live PML4 and the first</p><blockquote><p>448-byte ISO read corrupted the page tables into a triple fault.</p></blockquote><p><strong>Input</strong>: one argument — the built ELF (<code>check_bss.py &lt;elf&gt;</code>).</p><p><strong>Check logic</strong>:</p><ol><li>Run <code>nm -S -n &lt;elf&gt;</code>; collect every <code>b</code>/<code>B</code> symbol with address and size (3-column lines get size 0).</li><li>Locate the layout markers <code>__boot_pml4</code> (boot zone start), <code>__ocse_work_start</code>, <code>__end_of_kernel</code> (the <code>.ocsework</code> NOLOAD work zone added in WP-06c for the GUI wizard state).</li><li>Any marker missing → <code>FATAL: layout markers not found</code>, exit 1 (a mis-linked ELF is itself a failure).</li><li>A symbol is a violation when it overlaps <code>[__boot_pml4, __ocse_work_start)</code> and is not itself a <code>__boot_*</code>/<code>__ocse_work_start</code>/<code>__end_of_kernel</code> marker. Symbols fully inside the work zone are LEGAL (the loader zeroes it via <code>p_memsz</code>).</li></ol><p><strong>Failure output</strong> (exit 1):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[check_bss] FATAL: variables overlap the boot zone (0x...0..0x...1):</span></span>\n<span class="line"><span>  cli_buffer @0x...0+0x10000</span></span></code></pre></div><p>Success prints the headroom in bytes between the last regular variable and the boot zone — the number to watch when <code>.bss</code> grows.</p><p><strong>Enforced where</strong>: <code>tools/build_ocse_iso.sh</code> runs it on the ELF BEFORE packing — every <code>make ocse-iso</code> is gated. Any future overflow is a build error instead of a boot-time heisenbug.</p><h2 id="_3-tools-v2-registry-gate-py-—-v2-command-surface-freeze" tabindex="-1">3. tools/v2_registry_gate.py — v2 command-surface freeze <a class="header-anchor" href="#_3-tools-v2-registry-gate-py-—-v2-command-surface-freeze" aria-label="Permalink to &quot;3. tools/v2_registry_gate.py — v2 command-surface freeze&quot;">​</a></h2><p><strong>What it guards</strong>: the v2.0.0 group-B interface freeze — the declaration-collected command registry must not change shape when the collection mechanism itself changes.</p><p><strong>Input</strong>: one argument — the ISO to boot (<code>python3 tools/v2_registry_gate.py &lt;iso&gt;</code>).</p><p><strong>Check logic</strong> (boots QEMU BIOS 512M via pexpect, <code>OC_TOOLS</code> env for the relocated QEMU, then sends <code>help -a</code>, <code>help -w</code>, <code>help</code>):</p><ol><li>Boot reached the <code>oc&gt;</code> prompt (TIMEOUT → <code>FAIL: no shell prompt</code>).</li><li>The registry collection log line <code>registry: file-local declarations collected</code> must be present.</li><li><code>help -a</code> parsed between the anchors <code>Available commands (A-Z):</code> and <code>Commands by work package:</code> — exactly 231 command lines (233 commands; health export/watch count as subcommands). Wrong count → <code>FAIL: expected 231 lines, got N</code>.</li><li><code>help -w</code> footer must print <code>Total: 233 commands.</code></li><li>The service-group view must render (recovery, watchdog, <code>=== l1 (</code>).</li></ol><p><strong>Failure output</strong>: one <code>FAIL:</code> line per missed check; the full serial log is dumped to <code>/tmp/vcheck/v2_gate_out.txt</code> for triage. Non-zero exit on any failure.</p><p><strong>Enforced where</strong>: release-time gate of the v2 era. The 3.x successor of the count invariant is the dynamic floor in the 31-check regression (see <a href="./ci-gates.html">ci-gates</a> §5): commands may be ADDED, never removed — the floor starts at 276 (the g3 baseline 275 + p0leak) and the current tree measures 284.</p><h2 id="_4-tools-gen-userprogs-py-—-registration-constraints" tabindex="-1">4. tools/gen_userprogs.py — registration constraints <a class="header-anchor" href="#_4-tools-gen-userprogs-py-—-registration-constraints" aria-label="Permalink to &quot;4. tools/gen_userprogs.py — registration constraints&quot;">​</a></h2><p><strong>What it guards</strong>: the embedded ring-3 program registry (<code>ocos/kernel/userprogs_data.h</code>, consumed by <code>core_userprog_lookup()</code>). No name is hand-registered in the kernel.</p><p><strong>Input</strong>: none (discovers from the tree; needs <code>nasm</code> + <code>gcc</code> on PATH). Called by <code>make userprogs</code>, by <code>make all</code> (first step), and by the <code>$(USERPROGS_HDR)</code> file rule.</p><p><strong>Check logic / constraints</strong>:</p><ol><li><strong>Discovery is mechanical</strong>: folder apps are <code>ocos/l1apps/&lt;name&gt;/</code> containing <code>main.c</code> or <code>main.asm</code> (program name = folder name; every <code>*.c</code> in the folder links together); legacy flat programs are <code>ocos/l1apps/*.{c,asm}</code> (name = basename, with their v2.x build mode). <code>_shared/</code> is a header-only library, never an app. <code>libfoo.c</code> routes to <code>tools/build_solib.py</code> (<code>solib_data.h</code>, not this header). <code>ld_so.c</code> builds with <code>ld_so.ld</code> @ 0x10000000.</li><li><strong>First action</strong>: regenerate <code>ocos/interface/l1svc_ops.h</code> via <code>gen_l1svc_ops.py</code> so wrapper apps always compile against the current L1SVC numbering (append-only contract; a failure there aborts with <code>gen_l1svc_ops.py failed</code>).</li><li><strong>Duplicate names are fatal</strong>: after a global A-Z sort of folder + flat programs, <code>fail(&quot;duplicate program names (folder vs flat?): [...]&quot;)</code> — a folder app may not shadow a flat program.</li><li><strong>Strict i18n gate</strong>: every app must carry <code>i18n/{en,zh}.json</code> resources (loaded via <code>i18n_load</code>); the generated per-app tables ride the build.</li><li><strong>Mode verification</strong>: <code>verify_elf()</code> checks <code>e_type</code>/<code>PT_INTERP</code> per build mode (exec/pie/pie-foo/ld_so) — a mis-linked program aborts the generation.</li><li><strong>Orphan purge</strong>: a full regeneration drops blobs whose sources no longer exist (deleting an app removes it from the registry).</li><li><strong>Idempotent emit</strong>: the header is written byte-compare guarded, so an unchanged tree regenerates nothing.</li></ol><p><strong>Failure output</strong>: <code>gen_userprogs: ERROR: &lt;reason&gt;</code> + exit 1 (duplicate names, missing resources, compile/link failures).</p><p><strong>Enforced where</strong>: <code>make all</code> (rebuilds the header first — the WP06g1 catch-2 gap), <code>make userprogs</code>, and the staleness gate <code>make userprogs-check</code> wired into <code>make dist</code> (any source &gt; 2 s newer than the header fails the dist with the &quot;STALE embedded user programs (fix1 int3_user incident class)&quot; message).</p><h2 id="_5-make-reproducible-check-—-byte-identical-rebuild-gate" tabindex="-1">5. make reproducible-check — byte-identical rebuild gate <a class="header-anchor" href="#_5-make-reproducible-check-—-byte-identical-rebuild-gate" aria-label="Permalink to &quot;5. make reproducible-check — byte-identical rebuild gate&quot;">​</a></h2><p><strong>What it guards</strong>: clean-build determinism of the kernel ELF (the G13 gate; the ISO-level determinism stack is below).</p><p><strong>Input</strong>: the current tree; runs two full sub-makes.</p><p><strong>Check logic</strong>: <code>clean</code> → <code>kernel</code> → <code>sha256sum</code> → copy ELF to <code>/tmp/.oc_repro_1.elf</code> → <code>clean</code> again → <code>kernel</code> again → <code>cmp -s</code>. Determinism sources verified by the target&#39;s comments: no <code>__DATE__</code>/<code>__TIME__</code>/<code>__TIMESTAMP__</code> in the tree, the OCBL ISO packer pins every timestamp/GUID/volume-serial, gcc/ld are deterministic for identical inputs+flags, link order is fixed by the wildcard expansion, <code>strip --strip-debug</code> removes path-bearing sections, and <code>SOURCE_DATE_EPOCH</code> is honored when the caller exports it.</p><p><strong>Failure output</strong>: <code>reproducible-check: FAIL - ELF differs:</code>, both SHA256s, the first three <code>cmp</code> difference bytes, and <code>exit 1</code>.</p><p><strong>Enforced where</strong>: <code>tools/build_release.sh</code> step 2 (a release cannot proceed past a FAIL), and the release SOP step 2 (see <a href="./process.html">process</a>).</p><h2 id="_6-tools-fat-zero-dates-py-—-fat-date-scrubber" tabindex="-1">6. tools/fat_zero_dates.py — FAT date scrubber <a class="header-anchor" href="#_6-tools-fat-zero-dates-py-—-fat-date-scrubber" aria-label="Permalink to &quot;6. tools/fat_zero_dates.py — FAT date scrubber&quot;">​</a></h2><p><strong>What it guards</strong>: byte-identical FAT payloads across builds minutes apart. <code>mformat</code>/<code>mmd</code>/<code>mcopy</code> stamp the current wall clock into directory entries, which would leak build time into the ISO.</p><p><strong>Input</strong>: one argument — the mtools FAT12/16 image (<code>fat_zero_dates.py &lt;img&gt;</code>; rewrites in place).</p><p><strong>Check logic</strong>: parse the BPB (bytes-per-sector, sectors-per-cluster, FAT start/size, root dir location); walk every directory entry and zero ONLY the date/time fields — creation tenth (byte 13), creation time (14–15), creation date (16–17), last-access date (18–19), write time (22–23), write date (24–25) — leaving names, attributes, cluster chains and file sizes untouched. FAT12 chains are followed entry-by- entry to walk subdirectories.</p><p><strong>Failure output</strong>: none by design (a malformed image raises); the gate that consumes the image (the ISO packer&#39;s determinism seals) catches downstream drift.</p><p><strong>Enforced where</strong>: the FAT-image build path used by the install/update tooling before images are embedded or packed. Its ISO-side sibling is <code>tools/iso_zero_ctime.py</code> (rewrites Rock Ridge TF ctime/atime stamps to 1970 epoch in every ISO9660 directory record — xorriso hardcodes ctime to assembly time and <code>-alter_date</code> offers no ctime knob; the directory-atime leak was fixed in WP04-fix1). Together with the packer&#39;s pinned volume dates, node mtime/atime, GPT disk GUID and ESP volume serial, they form the G13 determinism stack that <code>reproducible-check</code> + the release SHA256 three-way check verify.</p><h2 id="_7-tools-fix-file-headers-py-—-stale-file-comment-rewriter" tabindex="-1">7. tools/fix_file_headers.py — stale <code>* File:</code> comment rewriter <a class="header-anchor" href="#_7-tools-fix-file-headers-py-—-stale-file-comment-rewriter" aria-label="Permalink to &quot;7. tools/fix_file_headers.py — stale `* File:` comment rewriter&quot;">​</a></h2><p><strong>What it guards</strong>: header-comment truth after the WP-10 project_restructure — files moved (e.g. <code>kernel/snd.c</code> → <code>drivers/snd/driver_snd.c</code>) but their <code>* File:</code> comments still pointed at the pre-restructure paths.</p><p><strong>Input</strong>: none (walks the repo).</p><p><strong>Check logic</strong>: walk every <code>.c</code>/<code>.h</code>/<code>.S</code>/<code>.asm</code> (skipping <code>.git</code>, <code>build</code>, <code>website</code>, <code>archive</code>, <code>iso</code>, and <code>tools/embed_grub.py</code>, whose matched line is a template header it WRITES, not its own header); in the first 15 lines, match <code>^(\\s*\\*\\s*File:\\s*)(\\S+)\\s*$</code>; rewrite the path to the file&#39;s actual repo-relative location. Comment-only — no semantics.</p><p><strong>Failure output</strong>: none (a hygiene tool); prints the lists of changed / already-correct / pathless files.</p><p><strong>Enforced where</strong>: one-shot after restructures; re-run it after any future tree-wide move so <code>grep &#39;* File:&#39;</code> stays a reliable index.</p><h2 id="_8-gate-summary-table" tabindex="-1">8. Gate summary table <a class="header-anchor" href="#_8-gate-summary-table" aria-label="Permalink to &quot;8. Gate summary table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guard</th><th>Input</th><th>Enforced by</th><th>Failure mode</th></tr></thead><tbody><tr><td><code>check_deps.py</code></td><td>tree</td><td>manual / pre-release</td><td>exit 1 + file:line list</td></tr><tr><td><code>check_bss.py</code></td><td>ELF</td><td><code>build_ocse_iso.sh</code> (every OCSE ISO)</td><td>exit 1 + symbol/address list</td></tr><tr><td><code>v2_registry_gate.py</code></td><td>ISO</td><td>release-time (v2 era)</td><td>FAIL lines + non-zero exit</td></tr><tr><td><code>gen_userprogs.py</code> constraints</td><td>tree</td><td><code>make all</code> / <code>make userprogs</code> / <code>make dist</code></td><td>abort with reason</td></tr><tr><td><code>userprogs-check</code> (make)</td><td>tree</td><td><code>make dist</code></td><td>exit 1, STALE message</td></tr><tr><td><code>reproducible-check</code> (make)</td><td>tree</td><td><code>build_release.sh</code> step 2 / SOP step 2</td><td>exit 1 + diff bytes</td></tr><tr><td><code>fat_zero_dates.py</code></td><td>FAT image</td><td>determinism stack</td><td>downstream hash mismatch</td></tr><tr><td><code>iso_zero_ctime.py</code></td><td>ISO</td><td>determinism stack</td><td>downstream hash mismatch</td></tr><tr><td><code>fix_file_headers.py</code></td><td>tree</td><td>one-shot hygiene</td><td>report only</td></tr><tr><td><code>ocse-vendor-check</code> (make)</td><td>tree</td><td><code>make ocse-elf</code></td><td>exit 1 + re-vendor instructions</td></tr></tbody></table><p>Vendor-side integrity (not a script but a rule): <code>ocse/</code> is vendor+edits output only — <code>ocse-vendor-check</code> fails when <code>ocse/kernel/types.h</code> is missing, and <code>tools/ocse_edits.py</code> is the single source of truth for every vendored-source edit (E1 OTA API stripped, E2 GRUB wrapper out, E3 net stack not vendored, E4 crash plumbing stubbed, E5 ring-3 kill removed). Never hand-edit <code>ocse/{kernel,drivers,fs,l1,boot,chinese}/*.c</code> — a re-vendor erases it.</p>',58)])])}const u=t(d,[["render",a]]);export{g as __pageData,u as default};
